(() => {
  const items = document.querySelectorAll('[class*="visualization"] [class*="item"], [role="radio"] ~ * > *, [data-testid*="visualization"]');
  const results = [];
  document.querySelectorAll('*').forEach(e => {
    const text = (e.textContent||'').trim();
    if(text && text.length < 40 && text !== '' && (e.closest('[role="radiogroup"]') || e.closest('[class*="vis"]'))) {
      results.push(text);
    }
  });
  return [...new Set(results)].slice(0, 30);
})()

(() => {
  const items = document.querySelectorAll('[class*="PluginVisualizationItem"]');
  return [...items].map(i => ({text: i.textContent.trim(), class: i.className.slice(0,60)}));
})()

(() => {
  const allWithText = [];
  document.querySelectorAll('[class*="item"], [role="presentation"] > *, [class*="visItem"], [class*="PluginListItem"]').forEach(e => {
    const t = e.textContent.trim();
    if(t && t.length < 50 && (t.includes('Text') || t.includes('text') || t === 'Text')) {
      allWithText.push(t + ' | class=' + e.className.slice(0,60) + ' | tag=' + e.tagName);
    }
  });
  return allWithText.slice(0,20);
})()

(() => {
  // Find all generic elements in the visualization picker area
  const items = document.querySelectorAll('[aria-label="Visualizations"] ~ div, [role="radiogroup"] ~ div *');
  const texts = [];
  document.querySelectorAll('span, div, button, a').forEach(e => {
    if(e.children.length === 0 || (e.children.length === 1 && e.children[0].tagName === 'IMG')) {
      const t = e.textContent.trim();
      if(t && t.length < 50 && !texts.includes(t)) texts.push(t);
    }
  });
  return texts.filter(t => t.length > 0).slice(0, 40);
})()

(() => {
  // Find the scrollable container for visualizations
  const scrollContainer = document.querySelector('[role="radiogroup"] ~ div, [class*="vis" i]');
  // Try to find it more broadly
  const containers = document.querySelectorAll('*');
  for(const c of containers) {
    if((c.scrollHeight > c.clientHeight) && c.textContent.includes('Time series') && c.textContent.includes('Heatmap')) {
      c.scrollTop = 300;
      return 'Scrolled: ' + c.tagName + ' ' + (c.className || '').slice(0,60);
    }
  }
  return 'No scrollable container found';
})()

(() => {
  const container = document.querySelector('[class*="scrollbar-view"]');
  if(container) {
    container.scrollTop = 600;
    return 'scrolled to 600, scrollHeight=' + container.scrollHeight;
  }
  return 'not found';
})()

(() => {
  const container = document.querySelector('[class*="scrollbar-view"]');
  if(container) {
    container.scrollTop = 200;
    return 'scrolled to 200, scrollHeight=' + container.scrollHeight + ', clientHeight=' + container.clientHeight;
  }
  return 'not found';
})()

(() => {
  // Find the actual scrollable container for the visualization list
  const all = document.querySelectorAll('*');
  const results = [];
  for(const el of all) {
    if(el.scrollHeight > 300 && el.textContent.includes('Time series') && el.textContent.includes('Bar gauge')) {
      results.push(el.tagName + ' ' + (el.className || '').slice(0,80) + ' scrollH=' + el.scrollHeight + ' clientH=' + el.clientHeight);
    }
  }
  return results.slice(0,5);
})()

(() => {
  // Find text nodes that say "Text" in the visualization picker
  const result = [];
  document.querySelectorAll('*').forEach(el => {
    if(el.textContent.trim() === 'Text' && el.children.length === 0 && el.parentElement) {
      result.push(el.tagName + ' | parent=' + el.parentElement.className.slice(0,60) + ' | text=' + el.textContent.trim());
    }
  });
  // Also look for "Text" case insensitively
  document.querySelectorAll('*').forEach(el => {
    if(/^Text$/.test(el.textContent.trim()) && el.children.length === 0 && el.parentElement) {
      result.push('E: ' + el.tagName + ' | parent=' + el.parentElement.className.slice(0,60));
    }
  });
  return [...new Set(result)].slice(0,10);
})()
